document.addEventListener("DOMContentLoaded",function(){var p=document.body.dataset.page;document.querySelectorAll("[data-page]").forEach(function(a){if(a.dataset.page===p)a.setAttribute("aria-current","page")});var b=document.querySelector(".toggle"),m=document.querySelector("#menu");if(!b)return;b.onclick=function(){var o=b.getAttribute("aria-expanded")!=="true";b.setAttribute("aria-expanded",String(o));b.setAttribute("aria-label",o?"메뉴 닫기":"메뉴 열기");m.classList.toggle("open",o)};m.querySelectorAll("a").forEach(function(a){a.onclick=function(){m.classList.remove("open");b.setAttribute("aria-expanded","false")}});document.onkeydown=function(e){if(e.key==="Escape"){m.classList.remove("open");b.setAttribute("aria-expanded","false")}}});